+                execute();
+            }
+        } finally {
+            lock.unlock();
+        }
+    }
+
+    class Flush implements Runnable {
+        @Override
+        public void run() {
+            lock.lock();
+            try {
+                if (closed) {
+                    return;
+                }
+                if (bulkRequest.numberOfActions() == 0) {
+                    return;
+                }
+                execute();
+            } finally {
+                lock.unlock();
+            }
+        }
+    }
+}

