+        source.source();    // build map
+        return filter.filterMap(source);
+    }
+
+    @Benchmark
+    public Source filterBytes() {
+        Source source = Source.fromBytes(sourceBytes);
+        source.source();    // build map
+        return filter.filterBytes(source);
+    }
